];

export const GRADE_LEVEL_LABELS_FR: Record<GradeLevel, string> = {
  prescolaire_1: "Préscolaire 01",
  prescolaire_2: "Préscolaire 02",
  "1ap": "1AP",
  "2ap": "2AP",
  "3ap": "3AP",
  "4ap": "4AP",
  "5ap": "5AP",
  "1am": "1AM",
  "2am": "2AM",
  "3am": "3AM",
  "4am": "4AM",
  "1ere_annee": "1ère Année",
  "2eme_annee": "2ème Année",
  "3eme_annee": "3ème Année",
};

/** Map a grade level to its academic level (primaire / cem / lycee). */
export function academicLevelFromGradeLevel(g: GradeLevel): AcademicLevel {
  switch (g) {
    case "prescolaire_1":
    case "prescolaire_2":
    case "1ap":
    case "2ap":
    case "3ap":
    case "4ap":
    case "5ap":
      return "primaire";
    case "1am":
    case "2am":
    case "3am":
    case "4am":
      return "cem";
    case "1ere_annee":
    case "2eme_annee":
    case "3eme_annee":
      return "lycee";
  }
}

/** Map a grade level to its 1-indexed year within its academic level. */
export function gradeYearFromGradeLevel(g: GradeLevel): number {
  switch (g) {
    case "prescolaire_1":
      return 0;
    case "prescolaire_2":
      return 0;
    case "1ap":
      return 1;
    case "2ap":
      return 2;
    case "3ap":
      return 3;
    case "4ap":
      return 4;
    case "5ap":
      return 5;
    case "1am":
      return 1;
    case "2am":
      return 2;
    case "3am":
      return 3;
    case "4am":
      return 4;
    case "1ere_annee":
      return 1;
    case "2eme_annee":
      return 2;
    case "3eme_annee":
      return 3;
  }
}

/** Inverse of `gradeYearFromGradeLevel` — best-effort fallback for legacy data. */
export function gradeLevelFromLevelYear(level: AcademicLevel, year: number): GradeLevel {
  if (level === "primaire") {
    if (year <= 0) return "prescolaire_2";
    switch (year) {
      case 1:
        return "1ap";
      case 2:
        return "2ap";
      case 3:
        return "3ap";
      case 4:
        return "4ap";
      default:
        return "5ap";
    }
  }
  if (level === "cem") {
    switch (year) {
      case 1:
        return "1am";
      case 2:
        return "2am";
      case 3:
        return "3am";
      default:
        return "4am";
    }
  }
  // lycee
  switch (year) {
    case 1:
      return "1ere_annee";
    case 2:
      return "2eme_annee";
    default:
      return "3eme_annee";
  }
}

