export const DEFAULT_CIRCULAR: Required<CircularModeConfig> = {
  ringCount: 3,
  baseRadius: 90,
  ringSpacing: 10,
  harmonicAmplitude: 3,
  angularVelocity: 0.002,
  counterRotationFactor: 0.8,
};

export const DEFAULT_LINEAR: Required<LinearModeConfig> = {
  barWidthFraction: 0.75,
  maxBarWidth: 500,
  barHeight: 24,
  waveRadius: 45,
  waveAmplitude: 12,
  progressSpeed: 0.5,
  waveColor: [110, 193, 228],
  waveColorSpeed: 0.3,
  baseColorRelaxationSpeed: 0.05,
};

/**
 * Update particle targets for the given mode.
 *
 * For `logo` mode this is a one-shot reset (call once on mode switch).
 * For `circular` and `linear` modes this should be called every frame
 * to produce continuous animation.
 *
 * Mutates `targetX`, `targetY`, `stiffness`, and (in `linear` mode) the
 * particle's `color` channel directly.
 */
export function updateTargets(
  particles: ParticleState[],
  mode: LogoMode,
  canvasWidth: number,
  canvasHeight: number,
  time: number,
  circularCfg: CircularModeConfig = {},
  linearCfg: LinearModeConfig = {},
  progressValue: { value: number },
): void {
  const n = particles.length;
  if (n === 0) return;

  const cx = canvasWidth / 2;
  const cy = canvasHeight / 2;

  switch (mode) {
    case "logo":
      morphToLogo(particles);
      break;
    case "circular":
      morphToCircular(particles, n, cx, cy, time, circularCfg);
      break;
    case "linear":
      morphToLinear(particles, n, cx, cy, canvasWidth, canvasHeight, time, linearCfg, progressValue);
      break;
  }
}

function morphToLogo(particles: ParticleState[]): void {
  for (const p of particles) {
    p.targetX = p.logoX;
    p.targetY = p.logoY;
    // Randomise stiffness slightly for organic feel.
    p.stiffness = 0.08 + Math.random() * 0.04;
  }
}

function morphToCircular(
  particles: ParticleState[],
  n: number,
  cx: number,
  cy: number,
  time: number,
  cfg: CircularModeConfig,
): void {
  const c = { ...DEFAULT_CIRCULAR, ...cfg };
  const t = time * c.angularVelocity;

  for (let i = 0; i < n; i++) {
    const p = particles[i];
    const ringIndex = i % c.ringCount;
    const baseAngle = (i / n) * Math.PI * 2 * 3;

    // Counter-rotating rings: even rings clockwise, odd rings counter-clockwise.
    const rotationSpeed = ringIndex % 2 === 0 ? t : -t * c.counterRotationFactor;
    const angle = baseAngle + rotationSpeed;

    // Radial harmonic oscillation prevents a rigid geometric look.
    const radius =
      c.baseRadius +
      ringIndex * c.ringSpacing +
      Math.sin(i * 0.05 + t) * c.harmonicAmplitude;

    p.targetX = cx + Math.cos(angle) * radius;
    p.targetY = cy + Math.sin(angle) * radius;
    p.stiffness = 0.03 + Math.random() * 0.02;
  }
}

function morphToLinear(
  particles: ParticleState[],
  n: number,
  cx: number,
  cy: number,
  canvasWidth: number,
  canvasHeight: number,
  time: number,
  cfg: LinearModeConfig,
  progressValue: { value: number },
): void {
  const c = { ...DEFAULT_LINEAR, ...cfg };

  const barWidth = Math.min(canvasWidth * c.barWidthFraction, c.maxBarWidth);
  const barHeight = c.barHeight;
  const startX = cx - barWidth / 2;
  const startY = cy - barHeight / 2;

  // Grid geometry — square-ish aspect from the bar dimensions.
  const cols = Math.max(1, Math.floor(Math.sqrt(n * (barWidth / barHeight))));
  const rows = Math.ceil(n / cols);

  // Advance progress (wraps from 100 → -20 so the wave re-enters from the left).
  progressValue.value += c.progressSpeed;
  if (progressValue.value > 100) progressValue.value = -20;

  const progressX = startX + (progressValue.value / 100) * barWidth;

  for (let i = 0; i < n; i++) {
    const p = particles[i];
    const col = i % cols;
    const row = Math.floor(i / cols);

    p.targetX = startX + (col / cols) * barWidth;
    p.targetY = startY + (row / rows) * barHeight;
    p.stiffness = 0.05 + Math.random() * 0.03;

    // Wave displacement.
    const distance = Math.abs(p.targetX - progressX);
    if (distance < c.waveRadius) {
      const wave = (c.waveRadius - distance) / c.waveRadius;
      p.targetY = cy - barHeight / 2 - Math.sin(p.targetX * 0.05 + time * 0.01) * c.waveAmplitude * wave;

      // Colour shift to cyan within wave envelope.
      p.color[0] += (c.waveColor[0] - p.color[0]) * c.waveColorSpeed;
      p.color[1] += (c.waveColor[1] - p.color[1]) * c.waveColorSpeed;
      p.color[2] += (c.waveColor[2] - p.color[2]) * c.waveColorSpeed;
    } else {
      // Relax target Y back toward the centre line.
      p.targetY += (cy - p.targetY) * 0.05;

      // Relax colour back toward base.
      for (let j = 0; j < 3; j++) {
        p.color[j] += (p.baseColor[j] - p.color[j]) * c.baseColorRelaxationSpeed;
      }
    }
  }
}

import type {
  ParticleState,
  RGB,
  Palette,
  PhysicsConfig,
  InteractionConfig,
} from "../types";
import { DEFAULT_PALETTE } from "../types";

/** Default physics configuration. */
export const DEFAULT_PHYSICS: Required<PhysicsConfig> = {
  damping: 0.88,
  stiffnessRange: [0.06, 0.10],
  sizeRange: [1.6, 3.0],
  colorProbabilities: [0.65, 0.20, 0.15],
  excitationColor: [239, 242, 243],
  excitationSpeed: 0.4,
  relaxationSpeed: 0.08,
  sizeExcitationMultiplier: 1.5,
  sizeRelaxationSpeed: 0.1,
};

/**
 * Create a new ParticleState from a projected canvas position.
 *
 * Particles spawn scattered around their target for a smooth entry
 * animation — the spring physics pulls them in over ~30 frames.
 */
export function createParticle(
  id: number,
  x: number,
  y: number,
  palette: Palette = DEFAULT_PALETTE,
  physics: PhysicsConfig = {},
): ParticleState {
  const cfg = { ...DEFAULT_PHYSICS, ...physics };

  const [stiffMin, stiffMax] = cfg.stiffnessRange;
  const [sizeMin, sizeMax] = cfg.sizeRange;
  const [pPrimary, pDeep] = cfg.colorProbabilities;

  const stiffness = stiffMin + Math.random() * (stiffMax - stiffMin);
  const baseSize = sizeMin + Math.random() * (sizeMax - sizeMin);

  // Weighted colour assignment.
  const roll = Math.random();
  let baseColor: RGB;
  if (roll < pPrimary) {
    baseColor = [...palette.primary] as RGB;
  } else if (roll < pPrimary + pDeep) {
    baseColor = [...palette.deep] as RGB;
  } else {
    baseColor = [...palette.accent] as RGB;
  }

  return {
    id,
    x: x + (Math.random() - 0.5) * 200,
    y: y + (Math.random() - 0.5) * 200,
    vx: 0,
    vy: 0,
    targetX: x,
    targetY: y,
    logoX: x,
    logoY: y,
    stiffness,
    damping: cfg.damping,
    baseSize,
    size: baseSize,
    baseColor,
    color: [...baseColor] as RGB,
  };
}

/**
 * Update a particle's physics state for one frame.
 *
 * Pipeline (in order):
 *   1. Mouse repulsion (if pointer active and within radius) — excites colour + size.
 *   2. Hooke's Law spring force toward target.
 *   3. Velocity damping.
 *   4. Euler position integration.
 *   5. Colour & size relaxation (when not excited).
 *
 * Mutates the particle in place for performance (avoids per-frame allocations).
 */
export function updateParticle(
  p: ParticleState,
  interaction: InteractionConfig,
  physics: PhysicsConfig = {},
): ParticleState {
  const cfg = { ...DEFAULT_PHYSICS, ...physics };

  if (interaction.active && interaction.pointerX !== null && interaction.pointerY !== null) {
    const dx = interaction.pointerX - p.x;
    const dy = interaction.pointerY - p.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < interaction.radius) {
      const force = (interaction.radius - dist) / interaction.radius;
      const angle = Math.atan2(dy, dx);
      p.vx -= Math.cos(angle) * force * interaction.force;
      p.vy -= Math.sin(angle) * force * interaction.force;

      // Pulse toward excitation colour on contact.
      for (let i = 0; i < 3; i++) {
        p.color[i] += (cfg.excitationColor[i] - p.color[i]) * cfg.excitationSpeed;
      }
      p.size = p.baseSize * cfg.sizeExcitationMultiplier;
    } else {
      easeColorAndSize(p, cfg);
    }
  } else {
    easeColorAndSize(p, cfg);
  }

  // Spring force toward target.
  p.vx += (p.targetX - p.x) * p.stiffness;
  p.vy += (p.targetY - p.y) * p.stiffness;

  // Damping.
  p.vx *= p.damping;
  p.vy *= p.damping;

  // Euler integration.
  p.x += p.vx;
  p.y += p.vy;

  return p;
}

function easeColorAndSize(p: ParticleState, cfg: Required<PhysicsConfig>): void {
  for (let i = 0; i < 3; i++) {
    p.color[i] += (p.baseColor[i] - p.color[i]) * cfg.relaxationSpeed;
  }
  p.size += (p.baseSize - p.size) * cfg.sizeRelaxationSpeed;
}

/** Compact frame representation used by the React canvas renderer. */
export function toFrameData(p: ParticleState): {
  id: number;
  x: number;
  y: number;
  size: number;
  color: RGB;
} {
  return {
    id: p.id,
    x: p.x,
    y: p.y,
    size: p.size,
    color: [
      Math.round(p.color[0]),
      Math.round(p.color[1]),
      Math.round(p.color[2]),
    ] as RGB,
  };
}

import { SamplingError } from "../errors";
import type { LoadedImage } from "../types";

/** Canvas size for the fallback pattern. */
export const FALLBACK_SIZE = 300;

/**
 * Generate the programmatic fallback pattern.
 *
 * Draws a bold "EI" monogram on a white background using Canvas 2D
 * primitives. The dark pixels of the glyph become particle target
 * positions in the downstream pipeline.
 */
export async function generateFallbackPattern(): Promise<LoadedImage> {
  try {
    const size = FALLBACK_SIZE;
    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) throw new SamplingError("Canvas 2D context unavailable");

    // White background (so the glyph produces dark-pixel targets).
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, size, size);

    // Bold "EI" monogram centred on the canvas.
    // The font size is tuned so the glyph fills ~70% of the canvas height,
    // matching the `fillRatio` default used by the projector.
    const fontSize = Math.floor(size * 0.55);
    ctx.fillStyle = "#000000";
    ctx.font = `bold ${fontSize}px Inter, "Helvetica Neue", Arial, sans-serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("EI", size / 2, size / 2);

    const imageData = ctx.getImageData(0, 0, size, size);
    return {
      data: imageData.data,
      width: size,
      height: size,
      channels: 4,
      sourceLabel: "<fallback-ei-monogram>",
    };
  } catch (err) {
    if (err instanceof SamplingError) throw err;
    throw new SamplingError(
      `Fallback pattern generation failed: ${(err as Error).message}`,
      err as Error,
    );
  }
}

import { ImageLoadError } from "../errors";
import type { ImageSource, LoadedImage } from "../types";

/** Default maximum dimension for the offscreen sampling canvas. */
const DEFAULT_MAX_DIM = 180;

/**
 * Load an image and downscale it to ≤ `maxDim` per side, preserving aspect
 * ratio. Returns raw RGBA pixel data via `<canvas>.getImageData()`.
 */
export async function loadImage(
  source: ImageSource,
  maxDim: number = DEFAULT_MAX_DIM,
): Promise<LoadedImage> {
  if (source.fallback) {
    // Delegated to fallback.ts to avoid a circular import.
    const { generateFallbackPattern } = await import("./fallback");
    return generateFallbackPattern();
  }

  let objectUrl: string | null = null;
  let img: HTMLImageElement;

  try {
    if (source.url) {
      img = await loadFromUrl(source.url);
    } else if (source.buffer) {
      const mime = source.mimeType ?? "image/png";
      const blob = new Blob([source.buffer as BlobPart], { type: mime });
      objectUrl = URL.createObjectURL(blob);
      img = await loadFromUrl(objectUrl);
    } else {
      throw new ImageLoadError("No image source provided (need url, buffer, or fallback)");
    }

    const { data, width, height, sourceLabel } = rasterize(img, source, maxDim);
    return { data, width, height, channels: 4, sourceLabel };
  } finally {
    if (objectUrl) URL.revokeObjectURL(objectUrl);
  }
}

function loadFromUrl(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    // Only opt into CORS for remote http(s) assets. Same-origin public/
    // assets (`./intro-logo.png`) load from the Vite dev server in dev and
    // from `file://…/dist/` in the packaged Electron app, where the origin
    // is opaque (null) — `crossOrigin = "anonymous"` would force a CORS
    // check that can never succeed and break every static-asset load.
    // Remote http(s) URLs keep the attribute so canvas `getImageData()`
    // stays un-tainted when the server sends ACAO headers.
    if (/^https?:\/\//i.test(url)) {
      img.crossOrigin = "anonymous";
    }
    img.onload = () => resolve(img);
    img.onerror = () => reject(new ImageLoadError(`Failed to load image from URL: ${url}`));
    img.src = url;
  });
}

function rasterize(
  img: HTMLImageElement,
  source: ImageSource,
  maxDim: number,
): { data: Uint8ClampedArray; width: number; height: number; sourceLabel: string } {
  const naturalW = img.naturalWidth || img.width;
  const naturalH = img.naturalHeight || img.height;
  if (naturalW <= 0 || naturalH <= 0) {
    throw new ImageLoadError(`Invalid image dimensions: ${naturalW}x${naturalH}`);
  }

  // Aspect-preserving downscale.
  const scale = Math.min(1, maxDim / Math.max(naturalW, naturalH));
  const w = Math.max(1, Math.round(naturalW * scale));
  const h = Math.max(1, Math.round(naturalH * scale));

  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) throw new ImageLoadError("Canvas 2D context unavailable");
  ctx.drawImage(img, 0, 0, w, h);

  const imageData = ctx.getImageData(0, 0, w, h);
  return {
    data: imageData.data,
    width: w,
    height: h,
    sourceLabel: source.url ?? `<buffer:${w}x${h}>`,
  };
}

import type { PipelineConfig } from "../types";
import { ImageLoadError } from "../errors";
import { loadImage } from "./image-loader";
import { samplePixels, type SamplingResult } from "./sampler";
import { projectPoints, type ProjectionResult } from "./projector";
import { generateFallbackPattern } from "./fallback";

export interface PipelineResult {
  /** Projected particle positions in canvas space. */
  projection: ProjectionResult;
  /** Sampling statistics. */
  sampling: SamplingResult;
  /** Image metadata. */
  image: {
    width: number;
    height: number;
    sourceLabel: string;
  };
}

/** Progress callback signature — receives a fraction in [0, 1] and a status message. */
export type ProgressCallback = (progress: number, message: string) => void;

/**
 * Execute the full image import pipeline.
 *
 * @param config   - Pipeline configuration.
 * @param onProgress - Optional progress callback (called 5 times during a successful run).
 */
export async function executePipeline(
  config: PipelineConfig,
  onProgress?: ProgressCallback,
): Promise<PipelineResult> {
  // ── Stage 1: Image Loading ──────────────────────────────────────────────
  onProgress?.(0.1, "Loading image source…");

  const maxDim = config.maxDim ?? 180;
  const loaded = config.source.fallback
    ? await generateFallbackPattern()
    : await loadImage(config.source, maxDim);

  onProgress?.(
    0.35,
    `Image loaded: ${loaded.width}x${loaded.height} from ${loaded.sourceLabel}`,
  );

  // ── Stage 2: Pixel Sampling ─────────────────────────────────────────────
  onProgress?.(0.5, "Sampling dark pixels…");

  const samplingResult = samplePixels(
    loaded.data,
    loaded.width,
    loaded.height,
    {
      density: config.density,
      luminanceThreshold: config.luminanceThreshold,
    },
  );

  if (samplingResult.darkPixelCount === 0) {
    throw new ImageLoadError(
      "No dark pixels found in the image. The image may be entirely white or too bright.",
    );
  }

  onProgress?.(
    0.7,
    `Sampled ${samplingResult.darkPixelCount} dark pixels from ${samplingResult.totalScanned} scanned`,
  );

  // ── Stage 3: Coordinate Projection ──────────────────────────────────────
  onProgress?.(0.85, "Projecting coordinates onto canvas…");

  const projectionResult = projectPoints(
    samplingResult.points,
    loaded.width,
    loaded.height,
    {
      canvasWidth: config.canvasWidth,
      canvasHeight: config.canvasHeight,
      fillRatio: config.fillRatio,
    },
  );

  onProgress?.(
    1.0,
    `Projection complete: ${projectionResult.points.length} particles at scale ${projectionResult.scale.toFixed(3)}`,
  );

  return {
    projection: projectionResult,
    sampling: samplingResult,
    image: {
      width: loaded.width,
      height: loaded.height,
      sourceLabel: loaded.sourceLabel,
    },
  };
}

import { ProjectionError } from "../errors";
import type { SamplePoint } from "./sampler";

export interface ProjectedPoint {
  x: number;
  y: number;
  sourceX: number;
  sourceY: number;
}

export interface ProjectionResult {
  points: ProjectedPoint[];
  scale: number;
  offsetX: number;
  offsetY: number;
  sourceWidth: number;
  sourceHeight: number;
}

export interface ProjectionConfig {
  canvasWidth: number;
  canvasHeight: number;
  /** Fraction of canvas to fill (0–1, default 0.7). */
  fillRatio?: number;
}

/**
 * Project offscreen sample points onto the main canvas.
 *
 * Applies a uniform scale so the sampled image fills `fillRatio` of the
 * canvas (70% by default), then centres the result.
 */
export function projectPoints(
  samplePoints: SamplePoint[],
  sourceWidth: number,
  sourceHeight: number,
  config: ProjectionConfig,
): ProjectionResult {
  try {
    const { canvasWidth, canvasHeight, fillRatio = 0.7 } = config;

    if (canvasWidth <= 0 || canvasHeight <= 0) {
      throw new ProjectionError(`Invalid canvas dimensions: ${canvasWidth}x${canvasHeight}`);
    }
    if (sourceWidth <= 0 || sourceHeight <= 0) {
      throw new ProjectionError(`Invalid source dimensions: ${sourceWidth}x${sourceHeight}`);
    }

    const scale = Math.min(
      (canvasWidth * fillRatio) / sourceWidth,
      (canvasHeight * fillRatio) / sourceHeight,
    );

    const offsetX = (canvasWidth - sourceWidth * scale) / 2;
    const offsetY = (canvasHeight - sourceHeight * scale) / 2;

    const points: ProjectedPoint[] = samplePoints.map((sp) => ({
      x: sp.x * scale + offsetX,
      y: sp.y * scale + offsetY,
      sourceX: sp.x,
      sourceY: sp.y,
    }));

    return {
      points,
      scale,
      offsetX,
      offsetY,
      sourceWidth,
      sourceHeight,
    };
  } catch (err) {
    if (err instanceof ProjectionError) throw err;
    throw new ProjectionError(
      `Projection failed: ${(err as Error).message}`,
      err as Error,
    );
  }
}

import { SamplingError } from "../errors";

export interface SamplePoint {
  x: number;
  y: number;
  /** Raw luminance value (0–255). */
  luminance: number;
}

export interface SamplingResult {
  points: SamplePoint[];
  width: number;
  height: number;
  darkPixelCount: number;
  totalScanned: number;
}

export interface SamplerConfig {
  /** Pixel step interval (lower = denser, default 2). */
  density?: number;
  /** Luminance threshold for dark-pixel detection (default 128). */
  luminanceThreshold?: number;
}

/**
 * Sample dark pixels from a raw RGBA buffer.
 *
 * For each pixel at step intervals of `density`, the luminance is
 * computed as the arithmetic mean of R, G, and B channels. If the
 * luminance falls below the threshold, the pixel coordinate is
 * included in the output.
 */
export function samplePixels(
  data: Uint8Array | Uint8ClampedArray,
  width: number,
  height: number,
  config: SamplerConfig = {},
): SamplingResult {
  const density = config.density ?? 2;
  const threshold = config.luminanceThreshold ?? 128;

  if (width <= 0 || height <= 0) {
    throw new SamplingError(`Invalid image dimensions: ${width}x${height}`);
  }

  try {
    const points: SamplePoint[] = [];
    let totalScanned = 0;

    for (let y = 0; y < height; y += density) {
      for (let x = 0; x < width; x += density) {
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        // Alpha channel (data[idx + 3]) is ignored for luminance.
        const lum = (r + g + b) / 3;
        totalScanned++;

        if (lum < threshold) {
          points.push({ x, y, luminance: lum });
        }
      }
    }

    return {
      points,
      width,
      height,
      darkPixelCount: points.length,
      totalScanned,
    };
  } catch (err) {
    throw new SamplingError(
      `Pixel sampling failed: ${(err as Error).message}`,
      err as Error,
    );
  }
}

export type LogoMode = "logo" | "circular" | "linear";

/** RGB triplet in [0, 255]. */
export type RGB = [number, number, number];

/** Full mutable particle state used by the physics step. */
export interface ParticleState {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  targetX: number;
  targetY: number;
  /** Original logo position — used when morphing back to `logo` mode. */
  logoX: number;
  logoY: number;
  stiffness: number;
  damping: number;
  baseSize: number;
  size: number;
  baseColor: RGB;
  color: RGB;
}

/** Brand palette for particle colour assignment. */
export interface Palette {
  primary: RGB;
  deep: RGB;
  accent: RGB;
}

/**
 * Default brand palette — mirrors the CSS variables in `src/index.css`:
 *   --brand-blue      #349BD4 → [52, 155, 212]
 *   --brand-blue-deep #2B7FB0 → [43, 127, 176]
 *   --brand-gold      #C8A98C → [200, 169, 140]
 */
export const DEFAULT_PALETTE: Palette = {
  primary: [52, 155, 212],
  deep: [43, 127, 176],
  accent: [200, 169, 140],
};

/** Image source for the pipeline. The renderer version supports URLs, blobs, and a programmatic fallback. */
export interface ImageSource {
  /** HTTP(S) URL or `data:` URI to load via HTMLImageElement. */
  url?: string;
  /** Raw encoded image bytes (PNG, JPEG, SVG, …). Wrapped in a Blob at runtime. */
  buffer?: Uint8Array;
  /** Optional MIME type hint when `buffer` is provided (default: `image/png`). */
  mimeType?: string;
  /** Use the built-in programmatic fallback pattern (El-Imtiyaz monogram). */
  fallback?: boolean;
}

/** Configuration for the import / sampling pipeline. */
export interface PipelineConfig {
  source: ImageSource;
  /** Maximum dimension for the offscreen sampling canvas (default 180). */
  maxDim?: number;
  /** Pixel step interval for sampling (lower = denser, default 2). */
  density?: number;
  /** Luminance threshold for dark-pixel detection (default 128). */
  luminanceThreshold?: number;
  /** Palette for particle colour assignment. */
  palette?: Palette;
  /** Canvas width for coordinate projection. */
  canvasWidth: number;
  /** Canvas height for coordinate projection. */
  canvasHeight: number;
  /** Fraction of canvas to fill (0–1, default 0.7). */
  fillRatio?: number;
}

/** Mouse / pointer interaction parameters. */
export interface InteractionConfig {
  /** Radius of the repulsion field in canvas pixels (default 100). */
  radius: number;
  /** Magnitude of the repulsion force (default 6.0). */
  force: number;
  /** Current pointer x position (null if inactive). */
  pointerX: number | null;
  /** Current pointer y position (null if inactive). */
  pointerY: number | null;
  /** Whether the pointer is currently active. */
  active: boolean;
}

/** Full physics simulation configuration. */
export interface PhysicsConfig {
  damping?: number;
  stiffnessRange?: [number, number];
  sizeRange?: [number, number];
  /** Colour probability distribution: [primary, deep, accent] (default [0.65, 0.20, 0.15]). */
  colorProbabilities?: [number, number, number];
  /** Excitation colour target (default near-white). */
  excitationColor?: RGB;
  excitationSpeed?: number;
  relaxationSpeed?: number;
  sizeExcitationMultiplier?: number;
  sizeRelaxationSpeed?: number;
}

export interface CircularModeConfig {
  ringCount?: number;
  baseRadius?: number;
  ringSpacing?: number;
  harmonicAmplitude?: number;
  /** Angular velocity in rad/ms (default 0.002). */
  angularVelocity?: number;
  counterRotationFactor?: number;
}

export interface LinearModeConfig {
  barWidthFraction?: number;
  maxBarWidth?: number;
  barHeight?: number;
  waveRadius?: number;
  waveAmplitude?: number;
  progressSpeed?: number;
  waveColor?: RGB;
  waveColorSpeed?: number;
  baseColorRelaxationSpeed?: number;
}

/** Complete configuration for the particle engine. */
export interface ParticleEngineConfig {
  pipeline: PipelineConfig;
  physics?: PhysicsConfig;
  interaction?: Partial<InteractionConfig>;
  circular?: CircularModeConfig;
  linear?: LinearModeConfig;
  initialMode?: LogoMode;
  /** Background colour used for the motion-blur clear step (default `rgba(36, 37, 38, 0.25)`). */
  background?: string;
}

/** A single simulation frame snapshot — consumed by the React canvas renderer. */
export interface SimulationFrame {
  /** Timestamp (epoch ms). */
  t: number;
  mode: LogoMode;
  /** Compact particle state — only the fields needed for rendering. */
  particles: Array<{
    id: number;
    x: number;
    y: number;
    size: number;
    color: RGB;
  }>;
}

/** Loaded image ready for sampling. */
export interface LoadedImage {
  /** RGBA pixel data (length = width × height × 4). */
  data: Uint8Array | Uint8ClampedArray;
  width: number;
  height: number;
  channels: 4;
  sourceLabel: string;
}

